INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('Reporting restrictions. For details please see Court Manager.','cy','GB','Cyfyngiadau adrodd. I gael manylion, ewch i weld Rheolwr y Llys.');
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('In chambers, no entry.','cy','GB','Barnwr yn y siambrau, dim mynediad.');
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('Members of the public are requested not to enter.','cy','GB',Unistr('Gofynnir i aelodau''r cyhoedd beidio \00e2 dod i mewn.'));
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('TV link in progress - please enter quietly.','cy','GB','Cyswllt Teledu ar waith - dewch i mewn yn ddistaw.');
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('Video being played - please enter quietly.','cy','GB','Fideo ar waith - dewch i mewn yn ddistaw.');
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('If you wish to enter, please do so quietly.','cy','GB','Os dymunwch ddod i mewn, gwnewch hynny''n ddistaw.');
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('Reporting restrictions lifted.','cy','GB','Codwyd y Cyfyngiadau Adrodd.');
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('Please switch off mobile phones.','cy','GB',UNISTR('Diffoddwch bob ff\00f4n symudol.'));
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('Food and drink must not be consumed in the courtrooms.','cy','GB','Ni chaniateir bwyta nac yfed yn ystafelloedd y llys.');
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('Bench warrant in progress.','cy','GB','Gwarant o''r fainc ar waith.');
