INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('The undermentioned cases have been included in the above list for hearing as shown. If it becomes necessary to alter a date of hearing, you will be notified of the change as soon as possible. Please inform the Listing Officer immediately of any matters likely to affect the listing of the case.','cy','GB',UNISTR('Mae''r achosion a nodir isod wedi''u cynnwys yn y rhestr uchod i''w clywed yn y drefn y maent yn ymddangos. Os bydd angen newid dyddiad y gwrandawiad byddwn yn eich hysbysu o''r newid cyn gynted \00e2 phosib. Wnewch chi roi gwybod i''r Swyddog Rhestru cyn gynted \00e2 phosib am unrhyw faterion sy''n debygol o effeithio ar amserlen rhestru''r achos.'));
INSERT INTO XHIBIT.XHB_REF_TRANSLATION (KEY, LANGUAGE, COUNTRY, TRANSLATION) VALUES ('Cases which have been designated as reserve cases are liable to be listed at short notice on any day during the period covered by the list.','cy','GB','Mae''r achosion sydd wedi eu dynodi fel achosion wrth gefn yn debygol o gael eu rhestru ar fyr rybudd ar unrhyw ddiwrnod yn ystod cyfnod y rhestr.');
